import { ref, onMounted } from 'vue';

// Create the useFetch composable function
function useFetch(url) {
  // Initialize reactive state variables here
  const data = ref(null);
  const loading = ref(true);
  const error = ref(null);

  // Define the fetchData function here
  async function fetchData() {
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error('Network response was not ok');
      data.value = await response.json();
    } catch (err) {
      error.value = err.message;
    } finally {
      loading.value = false;
    }
  }

  // Call fetchData on component mount
  onMounted(fetchData);

  // Return the reactive state here
  return { data, loading, error };
}

// Create the main Vue component here
export default {
  setup() {
    // Call useFetch here with a URL and destructure
    const { data, loading, error } = useFetch('https://jsonplaceholder.typicode.com/todos/1');

    return { data, loading, error };
  },
  template: `
    <div>
      <!-- Add conditional rendering here -->
    </div>
  `
}
